fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column by taking element j from each row i.
    // Preallocate a vector with capacity n for efficiency.
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        // Assume valid indices as per problem statement.
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Construct the transpose matrix of size m x n.
    // For each column j in original, produce a row in output by extracting column j.
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}